insert into public.ai_knowledge (kind, area, country_code, topic, title, summary, source_name, source_url, license, lang, status) values
('management','legal','CO','salario_minimo_vigente_2026',$k$Colombia: salario mínimo y auxilio de transporte 2026$k$,$k$Dato vigente a noviembre de 2026 según las fuentes consultadas (confirmar antes de liquidar). El Decreto 1469 de 2025 fijó el salario mínimo mensual legal vigente (SMMLV) de 2026 en $1.750.905, con un auxilio de transporte de $249.095 (Decreto 1470 de 2025), para un total de $2.000.000. El auxilio aplica a quienes devengan hasta dos salarios mínimos. El Consejo de Estado suspendió provisionalmente el decreto original y el Gobierno expidió el Decreto 0159 de febrero de 2026, que fija transitoriamente el salario mínimo mientras se profiere sentencia; la prensa reporta que el monto se mantiene. Hay decisiones judiciales pendientes: el valor definitivo podría cambiar. El salario mínimo es base de varios cálculos (aportes, prestaciones, multas). Dónde confirmar: Ministerio del Trabajo (mintrabajo.gov.co), normograma del Gobierno (Decretos 0159, 1469 y 1470) y un contador o abogado laboral.$k$,$k$Normograma - Decreto 0159 de 2026 (fija transitoriamente el salario mínimo)$k$,$k$https://cancilleria.gov.co/normograma/compilacion/docs/decreto_0159_2026.htm$k$,$k$Texto normativo de acceso público; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Valores de prensa (Holland & Knight, El Tiempo) como apoyo. Pendiente de confirmación con contador o abogado.$k$,'es','draft'),
('management','legal','CL','salario_minimo_vigente_2026',$k$Chile: ingreso mínimo mensual 2026$k$,$k$Dato vigente a noviembre de 2026 según las fuentes consultadas (confirmar). La Ley 21.751 fijó $539.000 desde el 1 de enero de 2026. La Ley 21.830 (Diario Oficial del 22 de junio de 2026) lo reajustó a $553.553 con vigencia desde el 1 de mayo de 2026 para trabajadores de 18 a 65 años (con efecto retroactivo), y $412.938 para menores de 18 y mayores de 65. La misma ley prevé un reajuste automático por IPC aplicado sobre ese monto entre mayo y diciembre de 2026, que corresponde a enero de 2027: el valor exacto aún debe confirmarse. El ingreso mínimo también afecta la gratificación legal y otros topes. Dónde confirmar: bcn.cl (Ley 21.830), mintrab.gob.cl y dt.gob.cl.$k$,$k$Biblioteca del Congreso Nacional - Ley 21.830$k$,$k$https://www.bcn.cl/leychile/navegar?idNorma=1225354$k$,$k$Texto normativo de acceso público; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador o abogado.$k$,'es','draft'),
('management','legal','BR','salario_minimo_vigente_2026',$k$Brasil: salario mínimo 2026$k$,$k$El Decreto 12.797 del 23 de diciembre de 2025 fijó el salario mínimo en R$ 1.621,00 desde el 1 de enero de 2026, con valor diario de R$ 54,04 y por hora de R$ 7,37 (Agência Gov). Es referencia para beneficios del INSS, BPC y otras prestaciones. Algunos estados tienen pisos salariales regionales superiores, y varias categorías tienen piso por convenio colectivo: confirmar el que aplica al cliente. Dónde confirmar: planalto.gov.br (decreto), gov.br/trabalho-e-emprego y el sindicato o convención colectiva de la categoría.$k$,$k$Planalto - Decreto 12.797/2025$k$,$k$https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12797.htm$k$,$k$Texto normativo de acceso público; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador o abogado.$k$,'es','draft'),
('management','legal','MX','salario_minimo_vigente_2026',$k$México: salario mínimo general y de la frontera norte 2026$k$,$k$Según la CONASAMI, reportado por EY, Garrigues y prensa, desde el 1 de enero de 2026 el salario mínimo general es de $315.04 diarios (aumento del 13 %), y de $440.87 diarios en la Zona Libre de la Frontera Norte. Hay además salarios mínimos profesionales (61 oficios) más altos, actualizados cada año. La publicación se cita en el DOF del 9 de diciembre de 2025. Una nota de prensa menciona $340.87 para la frontera: es un dato que contradice a las demás fuentes y se descarta; confirmar en la tabla oficial. Dónde confirmar: gob.mx/conasami (tabla de salarios mínimos 2026), Diario Oficial de la Federación y un contador.$k$,$k$EY México - Incremento a salarios mínimos 2026 (con base en CONASAMI)$k$,$k$https://www.ey.com/es_mx/technical/tax/boletines-fiscales/incremento-salarios-minimos-2026$k$,$k$Material informativo de firma privada que reproduce la resolución de la CONASAMI; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Fuente secundaria. Pendiente de confirmación con contador o abogado.$k$,'es','draft'),
('management','legal','PE','salario_minimo_vigente_2026',$k$Perú: Remuneración Mínima Vital 2026 (dos tramos)$k$,$k$El Decreto Supremo 015-2026-TR (El Peruano, 28 de septiembre de 2026) incrementa la RMV de S/ 1,130 a S/ 1,300 en dos tramos: el primero, de S/ 100, desde el 1 de octubre de 2026 (RMV vigente: S/ 1,230); el segundo, de S/ 70, se fijará con un nuevo decreto previsto para el primer semestre de 2027. Según el mismo reporte, la jornada nocturna (RMV más 35 %) sube a S/ 1,660.50 en el primer tramo y la subvención de modalidades formativas se iguala a la RMV. Prensa y LinkedIn técnico indican que la asignación familiar (10 % de la RMV) pasa de S/ 113 a S/ 123: confirmar. Se informó también un bono de S/ 100 por trabajador para micro y pequeñas empresas, con condiciones propias: confirmar. Dónde confirmar: elperuano.pe (DS 015-2026-TR), gob.pe/mtpe y un contador laboral.$k$,$k$El Peruano - Decreto Supremo 015-2026-TR$k$,$k$https://busquedas.elperuano.pe/dispositivo/EX/2559163-1$k$,$k$Texto normativo de acceso público; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador o abogado.$k$,'es','draft'),
('management','legal','AR','salario_minimo_vigente_2026',$k$Argentina: Salario Mínimo, Vital y Móvil con aumentos escalonados$k$,$k$El SMVM se actualiza por resoluciones del Consejo Nacional del Empleo, la Productividad y el Salario Mínimo, Vital y Móvil o, si no hay acuerdo, por el Gobierno. Según la prensa, la Resolución 4/2026 fijó un esquema mensual de septiembre de 2026 a abril de 2027, y desde el 1 de noviembre de 2026 el monto es de $398.800 para mensualizados con jornada completa ($1.994 por hora), con $437.000 previstos para abril de 2027. El Consejo fue convocado para el 26 de noviembre: pueden surgir cambios. Las prestaciones por desempleo se ligan al SMVM (entre 50 % y 100 %). Estos valores cambian cada mes: confirmar el vigente. Dónde confirmar: Boletín Oficial, argentina.gob.ar/trabajo (Consejo del Salario) y un contador laboral.$k$,$k$Prensa económica argentina sobre la Resolución 4/2026 del Consejo del Salario (fuente secundaria)$k$,$k$https://calcularsueldo.com.ar/?p=16314$k$,$k$Fuente periodística y de calculadoras; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Fuente secundaria: verificar en el Boletín Oficial. Pendiente de confirmación con contador o abogado.$k$,'es','draft'),
('management','legal','UY','salario_minimo_vigente_2026',$k$Uruguay: Salario Mínimo Nacional 2026 en dos tramos$k$,$k$El Decreto 64/025 (diciembre de 2025) fijó el Salario Mínimo Nacional en $24.572 mensuales desde el 1 de enero de 2026 y en $25.383 desde el 1 de julio de 2026, por un ajuste anual total del 7,54 % repartido en 4,1 % y 3,3 %. El jornal diario se calcula dividiendo el monto entre 25. El Decreto 11/026 fijó la Base de Prestaciones y Contribuciones (BPC) 2026 en $6.864 (Bloomberg Tax). Los salarios mínimos por categoría o sector (consejos de salarios) son distintos y suelen ser más altos: confirmar el que corresponde al cliente. Dónde confirmar: gub.uy/ministerio-trabajo-seguridad-social (normativa), impo.com.uy y bps.gub.uy.$k$,$k$MTSS Uruguay - Decreto 64/025 Salario Mínimo Nacional$k$,$k$https://www.gub.uy/ministerio-trabajo-seguridad-social/institucional/normativa/resolucion-n-64025-salario-minimo-nacional$k$,$k$Texto normativo de acceso público; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador o abogado.$k$,'es','draft'),
('management','legal','EC','salario_minimo_vigente_2026',$k$Ecuador: Salario Básico Unificado 2026$k$,$k$El Ministerio del Trabajo fijó el Salario Básico Unificado (SBU) 2026 en USD 482 mensuales (Acuerdo Ministerial MDT-2025-195 del 15 de diciembre de 2025), USD 12 más que en 2025, tras un acuerdo tripartito. Rige desde el 1 de enero de 2026. Existen tablas sectoriales con salarios mínimos por cargo (mesas sectoriales) distintas al SBU. El SBU sirve de base para multas, pensiones y aportes (la prensa lo reporta). Una columna de opinión estima el costo total para el empleador (con décimos mensualizados, aportes y fondos de reserva) en unos USD 656: es un cálculo de un tercero, confirmar. Dónde confirmar: trabajo.gob.ec y el portal del IESS.$k$,$k$Ministerio del Trabajo del Ecuador - Fijación del SBU$k$,$k$https://www.trabajo.gob.ec/wp-content/uploads/2026/03/Anexo-Fijacion-Salario-Basico-Planta-Central-2025.pdf$k$,$k$Documento oficial de acceso público; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador o abogado.$k$,'es','draft'),
('management','legal','PY','salario_minimo_vigente_2026',$k$Paraguay: salario mínimo legal con reajuste de julio de 2026$k$,$k$El Decreto 6225 del 17 de junio de 2026 dispuso el reajuste del 5 % del salario mínimo legal para actividades diversas no especificadas: G. 3.044.000 mensuales desde el 1 de julio de 2026 (aumento de G. 144.952), con jornal mínimo de G. 117.077 según el MTESS. La Resolución MTESS 670/2026 reglamenta los salarios y jornales mínimos y los salarios diferenciados por actividad (por ejemplo, mecánicos y guardias tienen montos propios, más altos). El trabajo nocturno lleva recargo del 30 %. La prensa reporta multas de 10 a 30 jornales mínimos por trabajador por no pagar el reajuste y un procedimiento de sumario abreviado del MTESS (monto de multas: confirmar). Dónde confirmar: mtess.gov.py (Resolución 670/2026) y un contador o abogado laboral.$k$,$k$Decreto 6225/2026 (texto publicado por impuestospy.com) y MTESS$k$,$k$https://impuestospy.com/impuestos/decreto-n-6225-2026/$k$,$k$Texto normativo difundido por un sitio privado; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Fuente secundaria: verificar en la Gaceta Oficial o el MTESS. Pendiente de confirmación con contador o abogado.$k$,'es','draft'),
('management','legal','BO','salario_minimo_vigente_2026',$k$Bolivia: Salario Mínimo Nacional 2026$k$,$k$El Decreto Supremo 5516 (13 de enero de 2026), reglamentado por la Resolución Ministerial 088/26, fija el Salario Mínimo Nacional en Bs 3.300 (aumento del 20 % desde Bs 2.750), aplicable desde el 2 de enero de 2026 para los sectores público y privado. Según el Ministerio de Trabajo, los empleadores debían presentar la Planilla Complementaria de Adecuación al Salario Mínimo Nacional 2026 por la Oficina Virtual de Trámites (los comunicados citan plazos distintos, 15 de abril y 15 de mayo: confirmar). Se aplican diferencias retroactivas y no se obliga a subir los salarios que ya superan el mínimo, según Ferrere. El Gobierno anunció diálogo a fines de 2026 para el nuevo mínimo: el monto puede cambiar. Dónde confirmar: mintrabajo.gob.bo, ovt.mintrabajo.gob.bo y la Gaceta Oficial.$k$,$k$Gaceta Oficial de Bolivia - Decreto Supremo 5516 (texto de consulta)$k$,$k$https://www.atb.com.bo/wp-content/uploads/2026/01/DS55161988NCPP.pdf$k$,$k$Texto normativo de acceso público; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador o abogado.$k$,'es','draft');